    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(4), 0x2000);
        let v = b.konst::<polyisa_sem::W16>(0x037F);
        b.set(polyisa_guest_x86::sem::fcw_ref(), v);
        Ok(())
    })
    .unwrap();
    env.backend
        .mem
        .write(VirtAddr(0x1000), &[0xD9, 0x7C, 0x24, 0x4E])
        .unwrap();
