#[test]
fn run_mulsd_xmm2_rdx_disp32() {
    // F2 0F 59 92 10 00 00 00 = mulsd xmm2, [rdx+0x10]。3.0*2.0 は 6.0。上位64は残る。
    // awk log 0x4c1636。Ref: SPEC-X86-INTEL-SDM (v093).
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    env.backend.mem.map(VirtAddr(0x2000), 1, Perms::RW).unwrap();
    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(2), 0x2000);
        Ok(())
    })
    .unwrap();
    env.backend
        .mem
        .write(VirtAddr(0x2010), &0x4000_0000_0000_0000u64.to_le_bytes())
        .unwrap();
    env.backend.mem.write(VirtAddr(0x2018), &[0xAB]).unwrap();
    env.backend.set(
        polyisa_guest_x86::sem::xmm_ref(polyisa_guest_x86::sem::Xmm(2)),
        0xAAAA_AAAA_AAAA_AAAA_4008_0000_0000_0000,
    );
    env.backend.set(polyisa_guest_x86::sem::eflags_ref(), 1);
    env.backend
        .mem
        .write(
            VirtAddr(0x1000),
            &[0xF2, 0x0F, 0x59, 0x92, 0x10, 0x00, 0x00, 0x00],
        )
        .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_mode(&mut env, 0x1000, &mut sys, 1, true);
    assert_eq!(out, Outcome::StepLimit { pc: 0x1008 });
    let v: u128 = env.backend.get(polyisa_guest_x86::sem::xmm_ref(
        polyisa_guest_x86::sem::Xmm(2),
    ));
    assert_eq!(v, 0xAAAA_AAAA_AAAA_AAAA_4018_0000_0000_0000);
    let rdx: u64 = polyisa_guest_x86::sem::read64(&mut env.backend, Gpr(2));
    assert_eq!(rdx, 0x2000);
    assert_eq!(env.backend.get(polyisa_guest_x86::sem::eflags_ref()), 1);
    let mut nb = [0u8; 9];
    env.backend
        .mem
        .read(
            VirtAddr(0x2010),
            &mut nb,
            polyisa_mem::Access {
                endian: polyisa_mem::Endian::Le,
                align: polyisa_mem::Align::Unaligned,
                kind: polyisa_mem::AccessKind::DataRead,
            },
        )
        .unwrap();
    assert_eq!(&nb[..8], &0x4000_0000_0000_0000u64.to_le_bytes());
    assert_eq!(nb[8], 0xAB);
}

