    let prog: &[u8] = &[
        0xD9, 0xE8, // fld1
        0xD9, 0xEE, // fldz
        0xDB, 0xE9, // fucomi st(1) → CF=1,ZF=0
        0x0F, 0x92, 0xC3, // setc bl
        0xB8, 0x01, 0x00, 0x00, 0x00, // mov eax,1
        0xCD, 0x80,
    ];
