#[test]
fn run_push_pop_es_ds() {
    // primary map の push es/pop ds（非64bit 専用）。
    let prog: &[u8] = &[
        0x66, 0xB8, 0x55, 0x00, // mov ax,0x55
        0x8E, 0xC0, // mov es,ax
        0x06, // push es
        0x1F, // pop ds
        0x8C, 0xDB, // mov bx,ds
        0x0F, 0xB7, 0xDB, // movzx ebx,bx
        0xB8, 0x01, 0x00, 0x00, 0x00, // mov eax,1
        0xCD, 0x80,
    ];
    let (out, _) = run32(prog, 100);
    assert_eq!(out, Outcome::Exit(0x55));
}

#[test]
fn run_arpl() {
    // ax.rpl=0 < bx.rpl=3 → ax=0x13・ZF=1 で分岐。
    let prog: &[u8] = &[
        0x66, 0xB8, 0x10, 0x00, // mov ax,0x10
        0x66, 0xBB, 0x23, 0x00, // mov bx,0x23
        0x63, 0xD8, // arpl ax,bx
        0x74, 0x07, // jz +7
        0xBB, 0xEF, 0xBE, 0x00, 0x00, // mov ebx,0xBEEF
        0xEB, 0x06, // jmp +6
        0x66, 0x89, 0xC3, // mov bx,ax
        0x0F, 0xB7, 0xDB, // movzx ebx,bx
        0xB8, 0x01, 0x00, 0x00, 0x00, // mov eax,1
        0xCD, 0x80,
    ];
    let (out, _) = run32(prog, 100);
    assert_eq!(out, Outcome::Exit(0x13));
}

#[test]
fn run_hlt_is_nop() {
    let prog: &[u8] = &[
        0xF4, // hlt（ユーザモード近似として nop）
        0xBB, 0x42, 0x00, 0x00, 0x00, // mov ebx,0x42
        0xB8, 0x01, 0x00, 0x00, 0x00, // mov eax,1
        0xCD, 0x80,
    ];
    let (out, _) = run32(prog, 100);
    assert_eq!(out, Outcome::Exit(0x42));
}

#[test]
fn run_sysenter_is_int80() {
    // sysenter は i386 syscall ABI と同じトラップで表す。
    let prog: &[u8] = &[
        0xBB, 0x77, 0x00, 0x00, 0x00, // mov ebx,0x77
        0xB8, 0x01, 0x00, 0x00, 0x00, // mov eax,1
        0x0F, 0x34, // sysenter
    ];
    let (out, _) = run32(prog, 100);
    assert_eq!(out, Outcome::Exit(0x77));
}

#[test]
fn run_sysexit_jumps() {
    // sysexit: edx→eip, ecx→esp。
    let mut prog = vec![
        0xBA, 0x20, 0x10, 0x00, 0x00, // mov edx,0x1020
        0xB9, 0x00, 0x20, 0x00, 0x00, // mov ecx,0x2000
        0x0F, 0x35, // sysexit
    ];
    prog.resize(0x20, 0x90);
    prog.extend_from_slice(&[
        0xBB, 0x5A, 0x00, 0x00, 0x00, // mov ebx,0x5A
        0xB8, 0x01, 0x00, 0x00, 0x00, // mov eax,1
        0xCD, 0x80,
    ]);
    let (out, _) = run32(&prog, 100);
    assert_eq!(out, Outcome::Exit(0x5A));
}

#[test]
fn run_mul_cl_r8() {
    // F6 E1 = mul cl。AL=20*CL=30 -> AX=600。上位非零で CF=OF=1。
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(0), 0xABCD_0014);
        polyisa_guest_x86::sem::write64(b, Gpr(1), 30);
        Ok(())
    })
    .unwrap();
    env.backend
        .mem
        .write(VirtAddr(0x1000), &[0xF6, 0xE1])
        .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_mode(&mut env, 0x1000, &mut sys, 1, true);
    assert_eq!(out, Outcome::StepLimit { pc: 0x1002 });
    assert_eq!(env.backend.get(Gpr(0).state()) & 0xFFFF, 600);
    assert_eq!(env.backend.get(Gpr(0).state()) >> 16, 0xABCD);
    assert_eq!(
        env.backend.get(polyisa_guest_x86::sem::eflags_ref()) & 0x801,
        0x801
    );
}

#[test]
fn run_imul_cl_r8() {
    // F6 E9 = imul cl。AL=-2 * CL=3 -> AX=-6=0xFFFA。上位は符号拡張で CF=OF=0。
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(0), 0xFE);
        polyisa_guest_x86::sem::write64(b, Gpr(1), 3);
        Ok(())
    })
    .unwrap();
    env.backend
        .mem
        .write(VirtAddr(0x1000), &[0xF6, 0xE9])
        .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_mode(&mut env, 0x1000, &mut sys, 1, true);
    assert_eq!(out, Outcome::StepLimit { pc: 0x1002 });
    assert_eq!(env.backend.get(Gpr(0).state()) & 0xFFFF, 0xFFFA);
    assert_eq!(
        env.backend.get(polyisa_guest_x86::sem::eflags_ref()) & 0x801,
        0
    );
}

