#[test]
fn run_fbstp_m80() {
    // fld dword [0x2000]=42.0f のあと DF 35 = fbstp [0x2100]。
    // 書き込みは 0x42 0x00*8 0x00。pop で top=0 に戻る。
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    env.backend.mem.map(VirtAddr(0x2000), 1, Perms::RW).unwrap();
    env.backend
        .mem
        .write(VirtAddr(0x2000), &0x4228_0000u32.to_le_bytes())
        .unwrap();
    env.backend
        .mem
        .write(
            VirtAddr(0x1000),
            &[
                0xD9, 0x05, 0xFA, 0x0F, 0x00, 0x00, // fld dword [0x2000]
                0xDF, 0x35, 0xF4, 0x10, 0x00, 0x00, // fbstp tbyte [0x2100]
            ],
        )
        .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_mode(&mut env, 0x1000, &mut sys, 2, true);
    assert_eq!(out, Outcome::StepLimit { pc: 0x100C });
    let mut buf = [0xAAu8; 10];
    env.backend
        .mem
        .read(VirtAddr(0x2100), &mut buf, polyisa_mem::Access::DATA_LE)
        .unwrap();
    assert_eq!(buf[0], 0x42);
    assert!(buf[1..10].iter().all(|b| *b == 0));
    assert_eq!(env.backend.get(polyisa_guest_x86::sem::top_ref()), 0);
}

#[test]
fn run_fnstsw_ax() {
    // fld 1.0; fcom 2.0 (C0=1); DF E0 = fnstsw ax -> AX=0x3900。
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    env.backend.mem.map(VirtAddr(0x2000), 1, Perms::RW).unwrap();
    env.backend
        .mem
        .write(VirtAddr(0x2000), &0x3f800000u32.to_le_bytes())
        .unwrap();
    env.backend
        .mem
        .write(VirtAddr(0x2004), &0x40000000u32.to_le_bytes())
        .unwrap();
    env.backend
        .mem
        .write(
            VirtAddr(0x1000),
            &[
                0xD9, 0x05, 0xFA, 0x0F, 0x00, 0x00, // fld dword [0x2000]
                0xD8, 0x15, 0xF8, 0x0F, 0x00, 0x00, // fcom dword [0x2004]
                0xDF, 0xE0, // fnstsw ax
            ],
        )
        .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_mode(&mut env, 0x1000, &mut sys, 3, true);
    assert_eq!(out, Outcome::StepLimit { pc: 0x100E });
    assert_eq!(env.backend.get(Gpr(0).state()) & 0xFFFF, 0x3900);
}

// ---- 16 ビット実モード ----

/// 実モード用の env。`entry` は IP。セグメントは個別に sregs へ設定する。
fn env16(prog: &[u8], entry: u32) -> BareEnv {
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0), 16, rwx).unwrap();
    env.backend
        .mem
        .map(VirtAddr(0x1_0000), 8, Perms::RW)
        .unwrap();
    env.backend.mem.write(VirtAddr(entry as u64), prog).unwrap();
    env
}

#[test]
fn run16_mov_ax_bx() {
    // 89 D8 = mov ax,bx（既定 osize は 16）。
    let mut env = env16(&[0x89, 0xD8], 0x1000);
    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(0), 0xAAAA_0000);
        polyisa_guest_x86::sem::write64(b, Gpr(3), 0x1234_5678);
        Ok(())
    })
    .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x1000, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x1002 });
    assert_eq!(env.backend.get(Gpr(0).state()), 0xAAAA_5678);
}

#[test]
fn run16_mov_eax_p66() {
    // 8088 には 0x66 接頭辞はなく、0x76 (jbe) の別名として実行される。
    // ZF=1 なら +2 分岐が取られ IP は 0x1004 へ進む。
    let mut env = env16(&[0x66, 0x02, 0x90, 0x90], 0x1000);
    env.backend.set(polyisa_guest_x86::sem::eflags_ref(), 0x40);
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x1000, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x1004 });
}

#[test]
fn run16_ea16_ds_base() {
    // 8B 07 = mov ax,[bx]。DS=0x100 の基底 0x1000 に BX=0x10 で 0x1010 を読む。
    let mut env = env16(&[0x8B, 0x07], 0x1000);
    env.backend.set(polyisa_guest_x86::sem::sreg_ref(3), 0x100);
    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(3), 0x10);
        Ok(())
    })
    .unwrap();
    env.backend
        .mem
        .write(VirtAddr(0x1010), &0xBEEFu16.to_le_bytes())
        .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x1000, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x1002 });
    assert_eq!(env.backend.get(Gpr(0).state()) & 0xFFFF, 0xBEEF);
}

#[test]
fn run16_ea16_bp_uses_ss() {
    // 8B 46 04 = mov ax,[bp+4]。BP 系の既定セグメントは SS。
    let mut env = env16(&[0x8B, 0x46, 0x04], 0x1000);
    env.backend.set(polyisa_guest_x86::sem::sreg_ref(2), 0x200);
    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(5), 0x20);
        Ok(())
    })
    .unwrap();
    env.backend
        .mem
        .write(VirtAddr(0x2024), &0xCAFEu16.to_le_bytes())
        .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x1000, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x1003 });
    assert_eq!(env.backend.get(Gpr(0).state()) & 0xFFFF, 0xCAFE);
}

#[test]
fn run16_seg_override_cs() {
    // 2E 8B 07 = mov ax, cs:[bx]。CS=0x100 の基底 0x1000 に BX=0x10 で
    // 0x1010 を読む。実モードでは CS セレクタがフェッチ基底でもあるため
    // IP=0 から CS*16=0x1000 のコードを実行する。
    let mut env = env16(&[0x2E, 0x8B, 0x07], 0x1000);
    env.backend.set(polyisa_guest_x86::sem::sreg_ref(1), 0x100);
    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(3), 0x10);
        Ok(())
    })
    .unwrap();
    env.backend
        .mem
        .write(VirtAddr(0x1010), &0xD00Du16.to_le_bytes())
        .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x3 });
    assert_eq!(env.backend.get(Gpr(0).state()) & 0xFFFF, 0xD00D);
}

#[test]
fn run16_push_pop_ss() {
    // SS=0x200（基底 0x2000）、SP=0x20。mov ax,0x42; push ax; pop bx。
    // push は SP-2=0x1E に書く（実番地 0x201E）。
    let mut env = env16(&[0xB8, 0x42, 0x00, 0x50, 0x5B], 0x1000);
    env.backend.set(polyisa_guest_x86::sem::sreg_ref(2), 0x200);
    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(4), 0x20);
        Ok(())
    })
    .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x1000, &mut sys, 3);
    assert_eq!(out, Outcome::StepLimit { pc: 0x1005 });
    assert_eq!(env.backend.get(Gpr(3).state()) & 0xFFFF, 0x42);
    assert_eq!(env.backend.get(Gpr(4).state()) & 0xFFFF, 0x20);
    let mut buf = [0u8; 2];
    env.backend
        .mem
        .read(VirtAddr(0x201E), &mut buf, polyisa_mem::Access::DATA_LE)
        .unwrap();
    assert_eq!(u16::from_le_bytes(buf), 0x42);
}

#[test]
fn run16_push_sp_wrap() {
    // SP=0 から push は SP=0xFFFE に書き、ESP 上位は保持する。
    let mut env = env16(&[0xB8, 0x42, 0x00, 0x50], 0x1000);
    env.backend.set(polyisa_guest_x86::sem::sreg_ref(2), 0x000);
    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(4), 0xABCD_0000);
        Ok(())
    })
    .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x1000, &mut sys, 2);
    assert_eq!(out, Outcome::StepLimit { pc: 0x1004 });
    assert_eq!(env.backend.get(Gpr(4).state()), 0xABCD_FFFE);
    let mut buf = [0u8; 2];
    env.backend
        .mem
        .read(VirtAddr(0xFFFE), &mut buf, polyisa_mem::Access::DATA_LE)
        .unwrap();
    assert_eq!(u16::from_le_bytes(buf), 0x42);
}

#[test]
fn run16_cs_base_fetch() {
    // CS=0x100 のときフェッチ番地は CS*16+IP。IP=0 → 0x1000。
    let mut env = env16(&[0xBB, 0x5A, 0x00], 0x1000);
    env.backend.set(polyisa_guest_x86::sem::sreg_ref(1), 0x100);
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x3 });
    assert_eq!(env.backend.get(Gpr(3).state()) & 0xFFFF, 0x5A);
}

#[test]
fn run16_movsb_ds_es() {
    // A4 = movsb。DS:SI から読み ES:DI に書く。
    // DS=0x100,ES=0x200、SI=5,DI=7 → 0x1005→0x2007。
    let mut env = env16(&[0xA4], 0x1000);
    env.backend.set(polyisa_guest_x86::sem::sreg_ref(3), 0x100);
    env.backend.set(polyisa_guest_x86::sem::sreg_ref(0), 0x200);
    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(6), 5);
        polyisa_guest_x86::sem::write64(b, Gpr(7), 7);
        Ok(())
    })
    .unwrap();
    env.backend.mem.write(VirtAddr(0x1005), &[0x77]).unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x1000, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x1001 });
    let mut buf = [0u8; 1];
    env.backend
        .mem
        .read(VirtAddr(0x2007), &mut buf, polyisa_mem::Access::DATA_LE)
        .unwrap();
    assert_eq!(buf[0], 0x77);
    // SI,DI はともに +1。
    assert_eq!(env.backend.get(Gpr(6).state()) & 0xFFFF, 6);
    assert_eq!(env.backend.get(Gpr(7).state()) & 0xFFFF, 8);
}

#[test]
fn run16_p67_asize32() {
    // 0x67 は 8088 ではアドレスサイズ接頭辞ではなく 0x77 (ja) の別名。
    // CF=0 かつ ZF=0 なら +2 分岐が取られる。
    let mut env = env16(&[0x67, 0x02, 0x90, 0x90], 0x1000);
    env.backend.set(polyisa_guest_x86::sem::eflags_ref(), 0);
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x1000, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x1004 });
}

#[test]
fn run16_ea16_word_wrap() {
    // 8B 07 = mov ax,[bx]。BX=0xFFFF, DS=0x100 → 下位は DS:0xFFFF（実番地
    // 0x1FFF）、上位はセグメント内折り返しで DS:0x0000（実番地 0x1000）。
    let mut env = env16(&[0x8B, 0x07], 0x4000);
    env.backend.set(polyisa_guest_x86::sem::sreg_ref(3), 0x100);
    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(3), 0xFFFF);
        Ok(())
    })
    .unwrap();
    env.backend.mem.write(VirtAddr(0x10FFF), &[0xAA]).unwrap();
    env.backend.mem.write(VirtAddr(0x1000), &[0xBB]).unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x4000, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x4002 });
    assert_eq!(env.backend.get(Gpr(0).state()) & 0xFFFF, 0xBBAA);
}

#[test]
fn run16_rep_movsw_wrap() {
    // F3 A5 = rep movsw。SI=0xFFFF の読みは 0xFFFF+0x0000 に折り返す。
    let mut env = env16(&[0xF3, 0xA5], 0x4000);
    env.backend.set(polyisa_guest_x86::sem::sreg_ref(3), 0x100); // DS
    env.backend.set(polyisa_guest_x86::sem::sreg_ref(0), 0x200); // ES
    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(1), 1); // CX
        polyisa_guest_x86::sem::write64(b, Gpr(6), 0xFFFF); // SI
        polyisa_guest_x86::sem::write64(b, Gpr(7), 4); // DI
        Ok(())
    })
    .unwrap();
    env.backend.mem.write(VirtAddr(0x10FFF), &[0xAA]).unwrap();
    env.backend.mem.write(VirtAddr(0x1000), &[0xBB]).unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x4000, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x4002 });
    let mut buf = [0u8; 2];
    env.backend
        .mem
        .read(VirtAddr(0x2004), &mut buf, polyisa_mem::Access::DATA_LE)
        .unwrap();
    assert_eq!(u16::from_le_bytes(buf), 0xBBAA);
    assert_eq!(env.backend.get(Gpr(6).state()) & 0xFFFF, 0x0001);
    assert_eq!(env.backend.get(Gpr(7).state()) & 0xFFFF, 0x0006);
}

#[test]
fn run16_setmo_cl() {
    // D3 F6 = setmo si,cl（8088 /6 undocumented）。CL=0 なら結果・旗とも不変、
    // CL!=0 なら SI=0xFFFF で論理旗型（SZP 更新、CF/OF/AF=0）。
    let mut env = env16(&[0xD3, 0xF6], 0x1000);
    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(1), 0);
        polyisa_guest_x86::sem::write64(b, Gpr(6), 0x1234);
        Ok(())
    })
    .unwrap();
    env.backend
        .set(polyisa_guest_x86::sem::eflags_ref(), 0x08D5);
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x1000, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x1002 });
    assert_eq!(env.backend.get(Gpr(6).state()) & 0xFFFF, 0x1234);
    assert_eq!(
        env.backend.get(polyisa_guest_x86::sem::eflags_ref()),
        0x08D5
    );

    let mut env = env16(&[0xD3, 0xF6], 0x1000);
    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(1), 5);
        polyisa_guest_x86::sem::write64(b, Gpr(6), 0x1234);
        Ok(())
    })
    .unwrap();
    env.backend
        .set(polyisa_guest_x86::sem::eflags_ref(), 0x08D5);
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x1000, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x1002 });
    assert_eq!(env.backend.get(Gpr(6).state()) & 0xFFFF, 0xFFFF);
    // SZP(0xFFFF)=SF|PF、CF/OF/AF=0。
    assert_eq!(
        env.backend.get(polyisa_guest_x86::sem::eflags_ref()) & 0x8D5,
        0x84
    );
}

#[test]
fn run16_daa_af_edges() {
    // DAA: AL=0x9E, AF=1, CF=0 → +6 のみ（第2補正なし）。8088 実測。
    let mut env = env16(&[0x27], 0x1000);
    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(0), 0x9E);
        Ok(())
    })
    .unwrap();
    env.backend.set(polyisa_guest_x86::sem::eflags_ref(), 0x10);
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x1000, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x1001 });
    assert_eq!(env.backend.get(Gpr(0).state()) & 0xFF, 0xA4);
    assert_eq!(env.backend.get(polyisa_guest_x86::sem::eflags_ref()) & 1, 0);

    // AL=0xFD, AF=0, CF=0 → +0x66（第2補正あり）。
    let mut env = env16(&[0x27], 0x1000);
    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(0), 0xFD);
        Ok(())
    })
    .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x1000, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x1001 });
    assert_eq!(env.backend.get(Gpr(0).state()) & 0xFF, 0x63);
    assert_eq!(env.backend.get(polyisa_guest_x86::sem::eflags_ref()) & 1, 1);
}

#[test]
fn run16_aaa_independent_ah() {
    // AAA: AX=0x72FF → AH+1 と AL+6 は独立（桁上げは伝搬しない）→ 0x7305。
    let mut env = env16(&[0x37], 0x1000);
    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(0), 0x72FF);
        Ok(())
    })
    .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x1000, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x1001 });
    assert_eq!(env.backend.get(Gpr(0).state()) & 0xFFFF, 0x7305);
    assert_eq!(
        env.backend.get(polyisa_guest_x86::sem::eflags_ref()) & 0x11,
        0x11
    );
}

#[test]
fn run16_imul8_flags() {
    // F6 2F = imul byte [bx]。AL=0xEC（-20）* [bx]=0x06 → AX=0xFF88。
    // IMUL 旗: chk = AH - sext(AL) = 0xFF - 0xFF = 0 → Z=1,S=0,P=1、
    // CF=OF=0、AF = AL<0 && AH&0xF==0xF → 1（8088 実測）。
    let mut env = env16(&[0xF6, 0x2F], 0x1000);
    env.backend.set(polyisa_guest_x86::sem::sreg_ref(3), 0x200);
    env.step(|b| {
        polyisa_guest_x86::sem::write64(b, Gpr(0), 0xEC);
        polyisa_guest_x86::sem::write64(b, Gpr(3), 0x10);
        Ok(())
    })
    .unwrap();
    env.backend.mem.write(VirtAddr(0x2010), &[0x06]).unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x1000, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x1002 });
    assert_eq!(env.backend.get(Gpr(0).state()) & 0xFFFF, 0xFF88);
    // OF|SF|ZF|AF|PF|CF = 0|0|1|1|1|0
    assert_eq!(
        env.backend.get(polyisa_guest_x86::sem::eflags_ref()) & 0x8D5,
        0x54
    );
}

#[test]
fn run16_int3_ivt() {
    // CC = int3。FLAGS/CS/次の IP を SS:SP-6 へ積み IVT[3] (0x0C) へ飛ぶ。
    // 積まれる FLAGS は IF/TF クリア前の元値、IF/TF はクリアされる。
    let mut env = env16(&[0xCC], 0x1000);
    env.backend
        .mem
        .write(VirtAddr(0x0C), &[0x00, 0x04, 0x00, 0x03])
        .unwrap(); // IVT[3] = 0300:0400
    env.backend.set(polyisa_guest_x86::sem::sreg_ref(2), 0x200); // SS=0x200 → base 0x2000
    env.backend.set(Gpr(4).state(), 0x1000); // SP
    env.backend
        .set(polyisa_guest_x86::sem::eflags_ref(), 0xF302);
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x1000, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x0400 });
    assert_eq!(env.backend.get(Gpr(4).state()) & 0xFFFF, 0x0FFA);
    let mut stk = [0u8; 6];
    env.backend
        .mem
        .read(
            VirtAddr(0x2FFA),
            &mut stk,
            polyisa_mem::Access {
                endian: polyisa_mem::Endian::Le,
                align: polyisa_mem::Align::Unaligned,
                kind: polyisa_mem::AccessKind::DataRead,
            },
        )
        .unwrap();
    assert_eq!(stk, [0x01, 0x10, 0x00, 0x00, 0x02, 0xF3]); // ip_next, cs, flags
    assert_eq!(
        env.backend.get(polyisa_guest_x86::sem::eflags_ref()) & 0x300,
        0
    );
    assert_eq!(env.backend.get(polyisa_guest_x86::sem::sreg_ref(1)), 0x0300);
}

#[test]
fn run16_gdtr_idtr_roundtrip() {
    // 実モードは CPL0 相当なので LGDT/LIDT を実行できる。
    // 16 ビット addressing の mod=00/rm=110 は disp16 直参照。
    let prog = &[
        0x0F, 0x01, 0x16, 0x00, 0x21, // lgdt [0x2100]
        0x0F, 0x01, 0x06, 0x00, 0x22, // sgdt [0x2200]
        0x0F, 0x01, 0x1E, 0x00, 0x21, // lidt [0x2100]
        0x0F, 0x01, 0x0E, 0x08, 0x22, // sidt [0x2208]
    ];
    let mut env = env16(prog, 0x1000);
    env.backend
        .mem
        .write(VirtAddr(0x2100), &[0x34, 0x12, 0xBC, 0x9A, 0x78, 0x56])
        .unwrap();
    let out = run16m(&mut env, 0x1000, "i286", 4);
    assert!(matches!(out, Outcome::StepLimit { .. }), "{out:?}");
    let acc = polyisa_mem::Access::DATA_LE;
    let mut a = [0u8; 6];
    let mut b = [0u8; 6];
    env.backend.mem.read(VirtAddr(0x2200), &mut a, acc).unwrap();
    env.backend.mem.read(VirtAddr(0x2208), &mut b, acc).unwrap();
    assert_eq!(a, [0x34, 0x12, 0xBC, 0x9A, 0x78, 0x56], "sgdt");
    assert_eq!(b, [0x34, 0x12, 0xBC, 0x9A, 0x78, 0x56], "sidt");
}

#[test]
fn run16_sysret_ud_ivt() {
    // SYSRET は実モードでは #UD。VM を止めず IVT[6] へ配送し、
    // フォールト命令の IP を積む。
    let mut env = env16(&[0x0F, 0x07], 0x1000);
    env.backend
        .mem
        .write(VirtAddr(0x18), &[0x00, 0x04, 0x00, 0x03])
        .unwrap(); // IVT[6] = 0300:0400
    env.backend.set(polyisa_guest_x86::sem::sreg_ref(2), 0x200);
    env.backend.set(Gpr(4).state(), 0x1000);
    let out = run16m(&mut env, 0x1000, "x86_64", 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x0400 });
    let mut stk = [0u8; 2];
    env.backend
        .mem
        .read(VirtAddr(0x2FFA), &mut stk, polyisa_mem::Access::DATA_LE)
        .unwrap();
    assert_eq!(u16::from_le_bytes(stk), 0x1000, "faulting ip");
}

#[test]
fn run16_iret() {
    // CF = iret。スタックから IP、CS、FLAGS を戻す（POPF と同じ強制ビット）。
    let mut env = env16(&[0xCF], 0x1000);
    env.backend.set(polyisa_guest_x86::sem::sreg_ref(2), 0x200);
    env.backend.set(Gpr(4).state(), 0x1000);
    env.backend
        .mem
        .write(VirtAddr(0x3000), &[0x00, 0x05, 0x00, 0x03, 0xFF, 0xFF])
        .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x1000, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x0500 }); // ip=0x0500 (cs=0x300)
    assert_eq!(env.backend.get(Gpr(4).state()) & 0xFFFF, 0x1006);
    assert_eq!(
        env.backend.get(polyisa_guest_x86::sem::eflags_ref()) & 0xFFFF,
        0xFFD7
    ); // 0xFFFF & 0x0FD5 | 0xF002
    assert_eq!(env.backend.get(polyisa_guest_x86::sem::sreg_ref(1)), 0x0300);
}

#[test]
fn run16_callf_ptr() {
    // 9A = callf ptr16:16。CS、次の IP の順に積んで far 分岐。
    // CS=0x0100 とすると CS:IP = 0100:1000 → 物理 0x2000 にコードを置く。
    let mut env = env16(&[0x9A, 0x00, 0x10, 0x00, 0x02], 0x2000);
    env.backend.set(polyisa_guest_x86::sem::sreg_ref(1), 0x0100);
    env.backend.set(polyisa_guest_x86::sem::sreg_ref(2), 0x200);
    env.backend.set(Gpr(4).state(), 0x1000);
    let mut sys = X64Exit;
    let out = run_x86::run_m16(&mut env, 0x1000, &mut sys, 1);
    assert_eq!(out, Outcome::StepLimit { pc: 0x1000 }); // ip=0x1000 (cs=0x200)
    assert_eq!(env.backend.get(Gpr(4).state()) & 0xFFFF, 0x0FFC);
    let mut stk = [0u8; 4];
    env.backend
        .mem
        .read(
            VirtAddr(0x2FFC),
            &mut stk,
            polyisa_mem::Access {
                endian: polyisa_mem::Endian::Le,
                align: polyisa_mem::Align::Unaligned,
                kind: polyisa_mem::AccessKind::DataRead,
            },
        )
        .unwrap();
    assert_eq!(stk, [0x05, 0x10, 0x00, 0x01]); // ip_next=0x1005, cs=0x0100
    assert_eq!(env.backend.get(polyisa_guest_x86::sem::sreg_ref(1)), 0x0200);
}

