fn run64_avx10_evex_vnni() {
    // byte: 10+1*5+2*6+3*7+4*8=80、word: 10+1*3+2*4=21。
    let feats = polyisa_guest_x86::model_feats("x86_64")
        | polyisa_guest_x86::FEAT_AVX10_2
        | polyisa_guest_x86::FEAT_AVX10
        | polyisa_guest_x86::FEAT_AVX512F
        | polyisa_guest_x86::FEAT_AVX512BW
        | polyisa_guest_x86::FEAT_AVX512CD
        | polyisa_guest_x86::FEAT_AVX512DQ
        | polyisa_guest_x86::FEAT_AVX512VL;
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    env.backend
        .set(polyisa_guest_x86::sem::zreg_ref(0, 0), u128::from(10u32));
    env.backend.set(
        polyisa_guest_x86::sem::zreg_ref(1, 0),
        u128::from(0x0002_0001u32),
    );
    env.backend.set(
        polyisa_guest_x86::sem::zreg_ref(2, 0),
        u128::from(0x0004_0003u32),
    );
    env.backend
        .mem
        .write(
            VirtAddr(0x1000),
            &[
                0x62, 0xF2, 0x74, 0x28, 0xD2, 0xC2, // vpdpwuud ymm0,ymm1,ymm2
                0x48, 0xC7, 0xC0, 0x3C, 0x00, 0x00, 0x00, // mov rax,60
                0x48, 0xC7, 0xC7, 0x00, 0x00, 0x00, 0x00, // mov rdi,0
                0x0F, 0x05, // syscall
            ],
        )
        .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_mode_ex(
        &mut env,
        0x1000,
        &mut sys,
        10,
        true,
        feats,
        &polyisa_guest_x86::model_params("x86_64"),
    );
    assert_eq!(out, Outcome::Exit(0));
    let v: u128 = env.backend.get(polyisa_guest_x86::sem::zreg_ref(0, 0));
    assert_eq!(v as u32, 21);
}

#[test]
fn run64_avx10_vmpsadbw_evex() {
    // imm=0 では先頭 4 バイト固定ブロックとの SAD を sliding window で計算する。
    // src1=1..16、src2=0 なので最初の 2 word は 1+2+3+4=10、2+3+4+5=14。
    let feats = polyisa_guest_x86::model_feats("x86_64")
        | polyisa_guest_x86::FEAT_AVX10_2
        | polyisa_guest_x86::FEAT_AVX10
        | polyisa_guest_x86::FEAT_AVX512F
        | polyisa_guest_x86::FEAT_AVX512BW
        | polyisa_guest_x86::FEAT_AVX512CD
        | polyisa_guest_x86::FEAT_AVX512DQ
        | polyisa_guest_x86::FEAT_AVX512VL;
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    let mut src1 = [0u8; 16];
    for (i, b) in src1.iter_mut().enumerate() {
        *b = i as u8 + 1;
    }
    env.backend.set(
        polyisa_guest_x86::sem::zreg_ref(1, 0),
        u128::from_le_bytes(src1),
    );
    env.backend
        .mem
        .write(
            VirtAddr(0x1000),
            &[
                0x62, 0xF3, 0x76, 0x28, 0x42, 0xC2, 0x00, // vmpsadbw ymm0,ymm1,ymm2,0
                0x48, 0xC7, 0xC0, 0x3C, 0x00, 0x00, 0x00, // mov rax,60
                0x48, 0xC7, 0xC7, 0x00, 0x00, 0x00, 0x00, // mov rdi,0
                0x0F, 0x05, // syscall
            ],
        )
        .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_mode_ex(
        &mut env,
        0x1000,
        &mut sys,
        10,
        true,
        feats,
        &polyisa_guest_x86::model_params("x86_64"),
    );
    assert_eq!(out, Outcome::Exit(0));
    let v: u128 = env.backend.get(polyisa_guest_x86::sem::zreg_ref(0, 0));
    assert_eq!(v as u32, 0x000e_000a);
}

#[test]
fn run64_avx10_fp8_to_bf16() {
    // E5M2 0x40=2.0 は BF16 0x4000、E4M3 0x38=1.0 は BF16 0x3f80。
    let feats = polyisa_guest_x86::model_feats("x86_64")
        | polyisa_guest_x86::FEAT_AVX10_3
        | polyisa_guest_x86::FEAT_AVX10_2
        | polyisa_guest_x86::FEAT_AVX10
        | polyisa_guest_x86::FEAT_AVX512F
        | polyisa_guest_x86::FEAT_AVX512BW
        | polyisa_guest_x86::FEAT_AVX512CD
        | polyisa_guest_x86::FEAT_AVX512DQ
        | polyisa_guest_x86::FEAT_AVX512VL;
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    env.backend
        .set(polyisa_guest_x86::sem::zreg_ref(1, 0), u128::from(0x40u8));
    env.backend
        .set(polyisa_guest_x86::sem::zreg_ref(3, 0), u128::from(0x38u8));
    env.backend
        .mem
        .write(
            VirtAddr(0x1000),
            &[
                0x62, 0xF5, 0xFF, 0x28, 0x1F, 0xC1, // vcvtbf82bf16 ymm0,xmm1
                0x62, 0xF5, 0x7F, 0x28, 0x1F, 0xD3, // vcvthf82bf16 ymm2,xmm3
                0x48, 0xC7, 0xC0, 0x3C, 0x00, 0x00, 0x00, // mov rax,60
                0x48, 0xC7, 0xC7, 0x00, 0x00, 0x00, 0x00, // mov rdi,0
                0x0F, 0x05, // syscall
            ],
        )
        .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_mode_ex(
        &mut env,
        0x1000,
        &mut sys,
        10,
        true,
        feats,
        &polyisa_guest_x86::model_params("x86_64"),
    );
    assert_eq!(out, Outcome::Exit(0));
    let v0: u128 = env.backend.get(polyisa_guest_x86::sem::zreg_ref(0, 0));
    let v2: u128 = env.backend.get(polyisa_guest_x86::sem::zreg_ref(2, 0));
    assert_eq!(v0 as u16, 0x4000);
    assert_eq!(v2 as u16, 0x3f80);
}

#[test]
fn run64_avx10_bf16_to_fp8() {
    // 2 ソース形は下位出力←src2、上位出力←src1。BF16 1.0→BF8 0x3c、
    // BF16 2.0→BF8 0x40。単一ソース HF8 では BF16 1.0→0x38。
    let feats = polyisa_guest_x86::model_feats("x86_64")
        | polyisa_guest_x86::FEAT_AVX10_3
        | polyisa_guest_x86::FEAT_AVX10_2
        | polyisa_guest_x86::FEAT_AVX10
        | polyisa_guest_x86::FEAT_AVX512F
        | polyisa_guest_x86::FEAT_AVX512BW
        | polyisa_guest_x86::FEAT_AVX512CD
        | polyisa_guest_x86::FEAT_AVX512DQ
        | polyisa_guest_x86::FEAT_AVX512VL;
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    env.backend.set(
        polyisa_guest_x86::sem::zreg_ref(1, 0),
        u128::from(0x4000u16),
    );
    env.backend.set(
        polyisa_guest_x86::sem::zreg_ref(2, 0),
        u128::from(0x3f80u16),
    );
    env.backend.set(
        polyisa_guest_x86::sem::zreg_ref(3, 0),
        u128::from(0x3f80u16),
    );
    env.backend
        .mem
        .write(
            VirtAddr(0x1000),
            &[
                0x62, 0xF2, 0xF7, 0x08, 0x74, 0xC2, // vcvt2bf162bf8 xmm0,xmm1,xmm2
                0x62, 0xF5, 0xFE, 0x08, 0x18, 0xD3, // vcvtbf162hf8 xmm2,xmm3
                0x48, 0xC7, 0xC0, 0x3C, 0x00, 0x00, 0x00, // mov rax,60
                0x48, 0xC7, 0xC7, 0x00, 0x00, 0x00, 0x00, // mov rdi,0
                0x0F, 0x05, // syscall
            ],
        )
        .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_mode_ex(
        &mut env,
        0x1000,
        &mut sys,
        10,
        true,
        feats,
        &polyisa_guest_x86::model_params("x86_64"),
    );
    assert_eq!(out, Outcome::Exit(0));
    let v0: u128 = env.backend.get(polyisa_guest_x86::sem::zreg_ref(0, 0));
    let v2: u128 = env.backend.get(polyisa_guest_x86::sem::zreg_ref(2, 0));
    let b0 = v0.to_le_bytes();
    assert_eq!(b0[0], 0x3c);
    assert_eq!(b0[8], 0x40);
    assert_eq!(v2 as u8, 0x38);
}

#[test]
fn run64_avx10_bias_bf16_to_fp8() {
    // BF16 0x3f9f は BF8 へ切り捨てると 0x3c。bias 0x10 が
    // 下位 5 bit へ加わり carry するため 0x3d になる。
    let feats = polyisa_guest_x86::model_feats("x86_64")
        | polyisa_guest_x86::FEAT_AVX10_3
        | polyisa_guest_x86::FEAT_AVX10_2
        | polyisa_guest_x86::FEAT_AVX10
        | polyisa_guest_x86::FEAT_AVX512F
        | polyisa_guest_x86::FEAT_AVX512BW
        | polyisa_guest_x86::FEAT_AVX512CD
        | polyisa_guest_x86::FEAT_AVX512DQ
        | polyisa_guest_x86::FEAT_AVX512VL;
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    env.backend
        .set(polyisa_guest_x86::sem::zreg_ref(1, 0), u128::from(0x10u8));
    env.backend.set(
        polyisa_guest_x86::sem::zreg_ref(2, 0),
        u128::from(0x3f9fu16),
    );
    env.backend
        .mem
        .write(
            VirtAddr(0x1000),
            &[
                0x62, 0xF2, 0xF4, 0x08, 0x74, 0xC2, // vcvtbiasbf162bf8 xmm0,xmm1,xmm2
                0x48, 0xC7, 0xC0, 0x3C, 0x00, 0x00, 0x00, // mov rax,60
                0x48, 0xC7, 0xC7, 0x00, 0x00, 0x00, 0x00, // mov rdi,0
                0x0F, 0x05, // syscall
            ],
        )
        .unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_mode_ex(
        &mut env,
        0x1000,
        &mut sys,
        10,
        true,
        feats,
        &polyisa_guest_x86::model_params("x86_64"),
    );
    assert_eq!(out, Outcome::Exit(0));
    let v0: u128 = env.backend.get(polyisa_guest_x86::sem::zreg_ref(0, 0));
    assert_eq!(v0 as u8, 0x3d);
}

