#[test]
fn run64_avx10_vpmldsabflydq() {
    // imm8=0: SRC1/SRC2 の low dword を A/B、Z は 128 bit 車線先頭の
    // low dword。A'=A+MontMul(B,Z)、B'=A-MontMul(B,Z) を Q 折りたたみで確認する。
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    let pack = |d0: u32, d2: u32| -> u128 { u128::from(d0) | (u128::from(d2) << 64) };
    env.backend
        .set(polyisa_guest_x86::sem::zreg_ref(0, 0), pack(1, 2));
    env.backend
        .set(polyisa_guest_x86::sem::zreg_ref(1, 0), pack(3, 4));
    env.backend
        .set(polyisa_guest_x86::sem::zreg_ref(2, 0), pack(5, 0));
    let mut prog = vec![0x62, 0xF3, 0xF5, 0x08, 0xDC, 0xC2, 0x00];
    prog.extend_from_slice(&avx10_exit_tail());
    env.backend.mem.write(VirtAddr(0x1000), &prog).unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_mode_ex(
        &mut env,
        0x1000,
        &mut sys,
        10,
        true,
        avx10_aux_feats() | polyisa_guest_x86::FEAT_AVX10_VPMLDSABFLYDQ,
        &polyisa_guest_x86::model_params("x86_64"),
    );
    assert_eq!(out, Outcome::Exit(0));
    let v0: u128 = env.backend.get(polyisa_guest_x86::sem::zreg_ref(0, 0));
    let d = |i: u32| ((v0 >> (i * 32)) & 0xffff_ffff) as u32;
    assert_eq!(
        [d(0), d(1), d(2), d(3)],
        [0x0065_a5a2, 0x001a_3a61, 0x005c_e783, 0x0022_f882]
    );
}

#[test]
fn run64_vsyscall() {
    // x86-64 の vsyscall 固定番地（gettimeofday/time/getcpu）を
    // call 経由で呼ぶ。ローダが写像するスタブページ
    // （mov eax,nr; syscall; ret）をここでも置く。実機の
    // 0xffffffffff600000 は eip の 32 ビット折りたたみで
    // 0xff600000 に届く。失敗なら exit(1..6)、全部通れば exit(42)。
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    env.backend.mem.map(VirtAddr(0x2000), 1, Perms::RW).unwrap();
    env.backend.mem.map(VirtAddr(0x3000), 1, Perms::RW).unwrap();
    env.backend.mem.map(VirtAddr(0xff60_0000), 1, rwx).unwrap();
    for (off, nr) in [(0u64, 96u32), (0x400, 201), (0x800, 309)] {
        let mut stub = vec![0xB8];
        stub.extend_from_slice(&nr.to_le_bytes());
        stub.extend_from_slice(&[0x0F, 0x05, 0xC3]);
        env.backend
            .mem
            .write(VirtAddr(0xff60_0000 + off), &stub)
            .unwrap();
    }
    env.backend.set(Gpr(4).state(), 0x2000);
    let prog: &[u8] = &[
        0xBF, 0x00, 0x30, 0x00, 0x00, // mov edi,0x3000 (tv)
        0x31, 0xF6, // xor esi,esi (tz=NULL)
        0x48, 0xB8, 0x00, 0x00, 0x60, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, // movabs rax,vsys gtod
        0xFF, 0xD0, // call rax
        0x48, 0x85, 0xC0, // test rax,rax
        0x75, 0x65, // jnz fail2
        0x8B, 0x04, 0x25, 0x00, 0x30, 0x00, 0x00, // mov eax,[0x3000]
        0x3D, 0x90, 0x51, 0x6D, 0x38, // cmp eax,946_688_400
        0x75, 0x54, // jnz fail3
        0xBF, 0x10, 0x30, 0x00, 0x00, // mov edi,0x3010 (tloc)
        0x48, 0xB8, 0x00, 0x04, 0x60, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, // movabs rax,vsys time
        0xFF, 0xD0, // call rax
        0x48, 0x3D, 0x90, 0x51, 0x6D, 0x38, // cmp rax,946_688_400
        0x75, 0x40, // jnz fail4
        0xBF, 0x20, 0x30, 0x00, 0x00, // mov edi,0x3020 (cpu)
        0xBE, 0x24, 0x30, 0x00, 0x00, // mov esi,0x3024 (node)
        0x48, 0xB8, 0x00, 0x08, 0x60, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, // movabs rax,vsys getcpu
        0xFF, 0xD0, // call rax
        0x48, 0x85, 0xC0, // test rax,rax
        0x75, 0x2B, // jnz fail5
        0x8B, 0x04, 0x25, 0x20, 0x30, 0x00, 0x00, // mov eax,[0x3020]
        0x85, 0xC0, // test eax,eax（cpu=0 であること）
        0x75, 0x1E, // jnz fail6
        0xBF, 0x2A, 0x00, 0x00, 0x00, // mov edi,42
        0xB8, 0x3C, 0x00, 0x00, 0x00, // mov eax,60 (exit)
        0x0F, 0x05, // syscall -> exit(42)
        // fail:
        0xBF, 0x01, 0x00, 0x00, 0x00, // mov edi,1
        0xB8, 0x3C, 0x00, 0x00, 0x00, // mov eax,60
        0x0F, 0x05, // syscall -> exit(1)
        // fail2:
        0xBF, 0x02, 0x00, 0x00, 0x00, // mov edi,2
        0xB8, 0x3C, 0x00, 0x00, 0x00, // mov eax,60
        0x0F, 0x05, // syscall -> exit(2)
        // fail3:
        0xBF, 0x03, 0x00, 0x00, 0x00, // mov edi,3
        0xB8, 0x3C, 0x00, 0x00, 0x00, // mov eax,60
        0x0F, 0x05, // syscall -> exit(3)
        // fail4:
        0xBF, 0x04, 0x00, 0x00, 0x00, // mov edi,4
        0xB8, 0x3C, 0x00, 0x00, 0x00, // mov eax,60
        0x0F, 0x05, // syscall -> exit(4)
        // fail5:
        0xBF, 0x05, 0x00, 0x00, 0x00, // mov edi,5
        0xB8, 0x3C, 0x00, 0x00, 0x00, // mov eax,60
        0x0F, 0x05, // syscall -> exit(5)
        // fail6:
        0xBF, 0x06, 0x00, 0x00, 0x00, // mov edi,6
        0xB8, 0x3C, 0x00, 0x00, 0x00, // mov eax,60
        0x0F, 0x05, // syscall -> exit(6)
    ];
    env.backend.mem.write(VirtAddr(0x1000), prog).unwrap();
    let mut sys = polyisa_os_linux::x86::Linux::x86_64();
    let out = run_x86::run_mode(&mut env, 0x1000, &mut sys, 1000, true);
    assert_eq!(out, Outcome::Exit(42));
}

/// VDPBF16PS の累積順序・NaN 優先順位・denormal flush。
/// acc + hi を先に RNE で丸め、次に lo を足す。1.0 + 2^-24 + 2^-24 は
/// 各ステップの丸めで 1.0 に戻る（単一回の丸めなら 1+2^-23 になる）。
#[test]
fn run_vdpbf16ps_accumulation_order_and_nan_priority() {
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    env.backend.mem.map(VirtAddr(0x2000), 1, Perms::RW).unwrap();
    let feats = polyisa_guest_x86::model_feats("x86_64_v3")
        | polyisa_guest_x86::FEAT_AVX10_2
        | polyisa_guest_x86::FEAT_AVX512F
        | polyisa_guest_x86::FEAT_AVX512VL;
    // acc: lane0=1.0, lane1=NaN, lane2=0, lane3=denormal
    let acc: &[u32] = &[0x3F800000, 0x7FC00099, 0x00000000, 0x00000001];
    // src1 bf16 pairs: lane0=(1.0,1.0), lane1=(hi=1.0,lo=NaN),
    // lane2=(denormal,denormal), lane3=(0,0)
    let x: &[u32] = &[0x3F803F80, 0x3F807FC1, 0x00010001, 0x00000000];
    // src2: lane0=(2^-24,2^-24), lane1=(2.0,2.0), lane2=(2.0,2.0), lane3=(0,0)
    let y: &[u32] = &[0x33803380, 0x40004000, 0x40004000, 0x00000000];
    for (i, v) in acc.iter().enumerate() {
        env.backend
            .mem
            .write(VirtAddr(0x2000 + 4 * i as u64), &v.to_le_bytes())
            .unwrap();
        env.backend
            .mem
            .write(VirtAddr(0x2010 + 4 * i as u64), &x[i].to_le_bytes())
            .unwrap();
        env.backend
            .mem
            .write(VirtAddr(0x2020 + 4 * i as u64), &y[i].to_le_bytes())
            .unwrap();
    }
    let prog: &[u8] = &[
        0x48, 0xB8, 0x00, 0x20, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // movabs rax,0x2000
        0x48, 0xBB, 0x00, 0x21, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // movabs rbx,0x2100
        0xC5, 0xFA, 0x6F, 0x00, // vmovdqu xmm0,[rax]
        0xC5, 0xFA, 0x6F, 0x48, 0x10, // vmovdqu xmm1,[rax+0x10]
        0xC5, 0xFA, 0x6F, 0x50, 0x20, // vmovdqu xmm2,[rax+0x20]
        0x62, 0xF2, 0x76, 0x08, 0x52, 0xC2, // vdpbf16ps xmm0,xmm1,xmm2
        0xC5, 0xFA, 0x7F, 0x03, // vmovdqu [rbx],xmm0
        0x48, 0xC7, 0xC0, 0x3C, 0x00, 0x00, 0x00, // mov rax,60
        0x48, 0x31, 0xFF, // xor rdi,rdi
        0x0F, 0x05, // syscall
    ];
    env.backend.mem.write(VirtAddr(0x1000), prog).unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_mode_ex(
        &mut env,
        0x1000,
        &mut sys,
        200,
        true,
        feats,
        &polyisa_guest_x86::model_params("x86_64_v3"),
    );
    assert_eq!(out, Outcome::Exit(0));
    let mut buf = [0u8; 16];
    env.backend
        .mem
        .read(VirtAddr(0x2100), &mut buf, polyisa_mem::Access::DATA_LE)
        .unwrap();
    let lane = |i: usize| u32::from_le_bytes(buf[i * 4..i * 4 + 4].try_into().unwrap());
    assert_eq!(
        lane(0),
        0x3F800000,
        "1.0+2^-24+2^-24 は各 step で 1.0 へ丸まる"
    );
    assert_eq!(lane(1), 0x7FC10000, "NaN は src1lo 優先で quiet 伝播");
    assert_eq!(lane(2), 0x00000000, "denormal 入力は zero 扱い");
    assert_eq!(lane(3), 0x00000000, "denormal の acc は zero 扱い");
}

/// PUSH2/POP2 の例外条件。#UD は RSP 被演算子と POP2 の同一レジスタ、
/// #GP は 16 バイト非整列の RSP。
struct ExcProbe {
    kind: Option<polyisa_sem::ExceptionKind>,
    addr: Option<u64>,
}
impl TrapHandler for ExcProbe {
    fn handle_trap(&mut self, env: &mut BareEnv, _code: u32) -> TrapOutcome {
        let nr = polyisa_guest_x86::sem::read64(&mut env.backend, Gpr(0));
        if nr == 60 {
            let code = polyisa_guest_x86::sem::read64(&mut env.backend, Gpr(7));
            TrapOutcome::Exit(code as u32)
        } else {
            TrapOutcome::Unimplemented
        }
    }
    fn handle_exception(
        &mut self,
        _env: &mut BareEnv,
        e: polyisa_sem::GuestException,
    ) -> TrapOutcome {
        self.kind = Some(e.kind);
        self.addr = e.addr;
        TrapOutcome::Exit(0)
    }
}

fn run_apx_exc(prog: &[u8], rsp: u64) -> (Option<polyisa_sem::ExceptionKind>, u64) {
    let feats = polyisa_guest_x86::model_feats("x86_64") | polyisa_guest_x86::FEAT_APX;
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    env.backend.mem.map(VirtAddr(0x2000), 1, Perms::RW).unwrap();
    env.backend.set(Gpr(4).state(), rsp as u32);
    env.backend
        .set(polyisa_guest_x86::sem::xcr0_ref(), 0x8_0003);
    env.backend.mem.write(VirtAddr(0x1000), prog).unwrap();
    let mut sys = ExcProbe {
        kind: None,
        addr: None,
    };
    let out = run_x86::run_mode_ex(
        &mut env,
        0x1000,
        &mut sys,
        50,
        true,
        feats,
        &polyisa_guest_x86::model_params("x86_64"),
    );
    assert_eq!(out, Outcome::Exit(0));
    let rsp_after = polyisa_guest_x86::sem::read64(&mut env.backend, Gpr(4));
    (sys.kind, rsp_after)
}

#[test]
fn run64_apx_push2pop2_exceptions() {
    use polyisa_sem::ExceptionKind;
    // push2 %rsp,%r12 → B/V が RSP で #UD。RSP は変わらない。
    let (k, rsp) = run_apx_exc(&[0x62, 0xF4, 0x1C, 0x18, 0xFF, 0xF4], 0x2800);
    assert_eq!(k, Some(ExceptionKind::Undefined), "rsp 被演算子は #UD");
    assert_eq!(rsp, 0x2800, "rsp は不変");

    // push2 %r12,%rsp → V が RSP で #UD。
    let (k, _) = run_apx_exc(&[0x62, 0xD4, 0x5C, 0x18, 0xFF, 0xF4], 0x2800);
    assert_eq!(k, Some(ExceptionKind::Undefined), "v が rsp でも #UD");

    // pop2 %r12,%r12 → 同一レジスタで #UD。
    let (k, _) = run_apx_exc(&[0x62, 0xD4, 0x1C, 0x18, 0x8F, 0xC4], 0x2800);
    assert_eq!(k, Some(ExceptionKind::Undefined), "pop2 の重複は #UD");

    // push2 %r13,%r12 で rsp が 16 バイト非整列 → #GP。
    // スタックにも RSP にも変更がないことを確かめる。
    let (k, rsp) = run_apx_exc(&[0x62, 0xD4, 0x1C, 0x18, 0xFF, 0xF5], 0x2808);
    assert_eq!(k, Some(ExceptionKind::Protection), "非整列は #GP");
    assert_eq!(rsp, 0x2808, "rsp は不変");

    // 整列していれば正常に 2 語積まれる。
    let feats = polyisa_guest_x86::model_feats("x86_64") | polyisa_guest_x86::FEAT_APX;
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    env.backend.mem.map(VirtAddr(0x2000), 1, Perms::RW).unwrap();
    env.backend.set(Gpr(4).state(), 0x2800);
    env.backend
        .set(polyisa_guest_x86::sem::xcr0_ref(), 0x8_0003);
    env.backend.set(Gpr(12).state(), 0x1111);
    env.backend.set(Gpr(13).state(), 0x2222);
    env.backend
        .mem
        .write(VirtAddr(0x1000), &[0x62, 0xD4, 0x1C, 0x18, 0xFF, 0xF5])
        .unwrap();
    let mut sys = ExcProbe {
        kind: None,
        addr: None,
    };
    let out = run_x86::run_mode_ex(
        &mut env,
        0x1000,
        &mut sys,
        1,
        true,
        feats,
        &polyisa_guest_x86::model_params("x86_64"),
    );
    assert_eq!(out, Outcome::StepLimit { pc: 0x1006 });
    assert_eq!(sys.kind, None, "整列時は例外なし");
    assert_eq!(
        polyisa_guest_x86::sem::read64(&mut env.backend, Gpr(4)),
        0x27F0,
        "rsp は 16 減る"
    );
    let mut buf = [0u8; 16];
    env.backend
        .mem
        .read(VirtAddr(0x27F0), &mut buf, polyisa_mem::Access::DATA_LE)
        .unwrap();
    assert_eq!(
        u64::from_le_bytes(buf[0..8].try_into().unwrap()),
        0x2222,
        "b64(rm) が低位"
    );
    assert_eq!(
        u64::from_le_bytes(buf[8..16].try_into().unwrap()),
        0x1111,
        "v64(ndd) が高位"
    );
}

/// AVX10 saturating conversion の MXCSR invalid/precision 生成。
#[test]
fn run_avx10_satcvt_mxcsr() {
    let feats = polyisa_guest_x86::model_feats("x86_64_v3")
        | polyisa_guest_x86::FEAT_AVX10_2
        | polyisa_guest_x86::FEAT_AVX512F
        | polyisa_guest_x86::FEAT_AVX512VL;
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    env.backend.mem.map(VirtAddr(0x2000), 1, Perms::RW).unwrap();
    // 入力: 3.7 / NaN / 5.0 / 1e300
    env.backend
        .mem
        .write(VirtAddr(0x2000), &3.7f64.to_le_bytes())
        .unwrap();
    env.backend
        .mem
        .write(VirtAddr(0x2008), &0x7FF8000000000001u64.to_le_bytes())
        .unwrap();
    env.backend
        .mem
        .write(VirtAddr(0x2010), &5.0f64.to_le_bytes())
        .unwrap();
    env.backend
        .mem
        .write(VirtAddr(0x2018), &1e300f64.to_le_bytes())
        .unwrap();
    // MXCSR 初期値 0x1F80（すべて mask）
    env.backend
        .mem
        .write(VirtAddr(0x2020), &0x1F80u32.to_le_bytes())
        .unwrap();
    let prog: &[u8] = &[
        0x48, 0xB8, 0x00, 0x20, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // movabs rax,0x2000
        0x48, 0xBB, 0x00, 0x21, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // movabs rbx,0x2100
        // case1: 3.7 → 3, precision
        0x0F, 0xAE, 0x50, 0x20, // ldmxcsr [rax+0x20]
        0xF2, 0x0F, 0x10, 0x08, // movsd xmm1,[rax]
        0x62, 0xF5, 0xFF, 0x08, 0x6D, 0xC1, // vcvttsd2sis xmm1,rax
        0x48, 0x89, 0x03, // mov [rbx],rax
        0x0F, 0xAE, 0x5B, 0x08, // stmxcsr [rbx+8]
        // case2: NaN → 0, invalid
        0x48, 0xB8, 0x08, 0x20, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // movabs rax,0x2008
        0x0F, 0xAE, 0x50, 0x18, // ldmxcsr [rax+0x18] (=0x2020)
        0xF2, 0x0F, 0x10, 0x08, // movsd xmm1,[rax]
        0x62, 0xF5, 0xFF, 0x08, 0x6D, 0xC1, // vcvttsd2sis xmm1,rax
        0x48, 0x89, 0x43, 0x10, // mov [rbx+0x10],rax
        0x0F, 0xAE, 0x5B, 0x18, // stmxcsr [rbx+0x18]
        // case3: 5.0 exact → flag なし
        0x48, 0xB8, 0x10, 0x20, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // movabs rax,0x2010
        0x0F, 0xAE, 0x50, 0x10, // ldmxcsr [rax+0x10] (=0x2020)
        0xF2, 0x0F, 0x10, 0x08, // movsd xmm1,[rax]
        0x62, 0xF5, 0xFF, 0x08, 0x6D, 0xC1, // vcvttsd2sis xmm1,rax
        0x48, 0x89, 0x43, 0x20, // mov [rbx+0x20],rax
        0x0F, 0xAE, 0x5B, 0x28, // stmxcsr [rbx+0x28]
        // case4: 1e300 → 飽和, invalid
        0x48, 0xB8, 0x18, 0x20, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // movabs rax,0x2018
        0x0F, 0xAE, 0x50, 0x08, // ldmxcsr [rax+0x8] (=0x2020)
        0xF2, 0x0F, 0x10, 0x08, // movsd xmm1,[rax]
        0x62, 0xF5, 0xFF, 0x08, 0x6D, 0xC1, // vcvttsd2sis xmm1,rax
        0x48, 0x89, 0x43, 0x30, // mov [rbx+0x30],rax
        0x0F, 0xAE, 0x5B, 0x38, // stmxcsr [rbx+0x38]
        0x48, 0xC7, 0xC0, 0x3C, 0x00, 0x00, 0x00, // mov rax,60
        0x48, 0x31, 0xFF, // xor rdi,rdi
        0x0F, 0x05, // syscall
    ];
    env.backend.mem.write(VirtAddr(0x1000), prog).unwrap();
    let mut sys = X64Exit;
    let out = run_x86::run_mode_ex(
        &mut env,
        0x1000,
        &mut sys,
        200,
        true,
        feats,
        &polyisa_guest_x86::model_params("x86_64_v3"),
    );
    assert_eq!(out, Outcome::Exit(0));
    let mut buf = [0u8; 0x40];
    env.backend
        .mem
        .read(VirtAddr(0x2100), &mut buf, polyisa_mem::Access::DATA_LE)
        .unwrap();
    let rd64 = |o: usize| u64::from_le_bytes(buf[o..o + 8].try_into().unwrap());
    let rd32 = |o: usize| u32::from_le_bytes(buf[o..o + 4].try_into().unwrap());
    assert_eq!(rd64(0), 3, "3.7 は 3 へ truncate");
    assert_eq!(rd32(8) & 0x20, 0x20, "fractional で precision");
    assert_eq!(rd32(8) & 1, 0, "in-range では invalid なし");
    assert_eq!(rd64(0x10), 0, "NaN は 0");
    assert_eq!(rd32(0x18) & 1, 1, "NaN で invalid");
    assert_eq!(rd64(0x20), 5, "5.0 は 5");
    assert_eq!(rd32(0x28) & 0x21, 0, "exact では flag なし");
    assert_eq!(rd64(0x30), i64::MAX as u64, "1e300 は飽和");
    assert_eq!(rd32(0x38) & 1, 1, "範囲外で invalid");
}

/// XGETBV の ECX!=0 と XSAVE/XRSTOR の 64 バイト非整列は #GP。
#[test]
fn run_xstate_fault_conditions() {
    use polyisa_sem::ExceptionKind;
    // xgetbv で ecx=1 → #GP
    let feats = polyisa_guest_x86::model_feats("x86_64") | polyisa_guest_x86::FEAT_APX;
    let run = |prog: &[u8], rcx: u64| {
        let mut env = bare_x86_env();
        let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
        env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
        env.backend.mem.map(VirtAddr(0x2000), 1, Perms::RW).unwrap();
        env.backend.set(Gpr(1).state(), rcx as u32);
        env.backend.set(Gpr(3).state(), 0x2008);
        env.backend
            .set(polyisa_guest_x86::sem::xcr0_ref(), 0x8_0003);
        env.backend.mem.write(VirtAddr(0x1000), prog).unwrap();
        let mut sys = ExcProbe {
            kind: None,
            addr: None,
        };
        let out = run_x86::run_mode_ex(
            &mut env,
            0x1000,
            &mut sys,
            1,
            true,
            feats,
            &polyisa_guest_x86::model_params("x86_64"),
        );
        // 例外時は probe が Exit(0)、成功時は 1 ステップで止まる。
        assert!(matches!(out, Outcome::Exit(0) | Outcome::StepLimit { .. }));
        sys.kind
    };
    // xgetbv = 0F 01 D0
    assert_eq!(
        run(&[0x0F, 0x01, 0xD0], 1),
        Some(ExceptionKind::Protection),
        "xgetbv ecx=1 は #GP"
    );
    assert_eq!(run(&[0x0F, 0x01, 0xD0], 0), None, "xgetbv ecx=0 は正常");
    // xsave [rbx] = 0F AE 23。rbx=0x2008 は 64 バイト非整列 → #GP
    assert_eq!(
        run(&[0x0F, 0xAE, 0x23], 0),
        Some(ExceptionKind::Protection),
        "xsave 非整列は #GP"
    );
    // xrstor [rbx] = 0F AE 2B
    assert_eq!(
        run(&[0x0F, 0xAE, 0x2B], 0),
        Some(ExceptionKind::Protection),
        "xrstor 非整列は #GP"
    );
}

#[test]
fn run_xrstor_xstate_bv_inconsistent_gp() {
    use polyisa_sem::ExceptionKind;
    // XSTATE_BV が XCR0 にない成分 bit を立てる復元は #GP。
    let feats = polyisa_guest_x86::model_feats("x86_64");
    let run = |xbv: u64, xcr0: u64| {
        let mut env = bare_x86_env();
        let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
        env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
        env.backend.mem.map(VirtAddr(0x2000), 1, Perms::RW).unwrap();
        env.backend
            .mem
            .write(
                VirtAddr(0x1000),
                &[
                    0x0F, 0xAE, 0x2B, // xrstor [rbx]
                    0x48, 0xC7, 0xC0, 0x3C, 0x00, 0x00, 0x00, // mov rax,60
                    0x48, 0x31, 0xFF, // xor rdi,rdi
                    0x0F, 0x05, // syscall
                ],
            )
            .unwrap();
        env.backend.set(Gpr(3).state(), 0x2000);
        env.backend.set(Gpr(0).state(), 0xffff_ffffu32);
        env.backend.set(Gpr(2).state(), 0xffff_ffffu32);
        env.backend.set(polyisa_guest_x86::sem::xcr0_ref(), xcr0);
        env.backend
            .mem
            .write(VirtAddr(0x2000 + 512), &xbv.to_le_bytes())
            .unwrap();
        env.backend
            .mem
            .write(VirtAddr(0x2000 + 24), &0x1f80u32.to_le_bytes())
            .unwrap();
        let mut sys = ExcProbe {
            kind: None,
            addr: None,
        };
        let out = run_x86::run_mode_ex(
            &mut env,
            0x1000,
            &mut sys,
            40,
            true,
            feats,
            &polyisa_guest_x86::model_params("x86_64"),
        );
        let _ = out;
        sys.kind
    };
    assert_eq!(
        run(0x200, 0x3),
        Some(ExceptionKind::Protection),
        "XSTATE_BV bit9 は XCR0=0x3 にないので #GP"
    );
    assert_eq!(run(0x3, 0x3), None, "XCR0 内の bit は正常");
    assert_eq!(run(0x200, 0x203), None, "bit9 が XCR0 にあれば正常");
}

#[test]
fn run64_avx10_saturating_conversion_unmasked_xm() {
    use polyisa_sem::ExceptionKind;
    // vcvttps2ibs で 1.5 を trunc すると inexact。MXCSR の precision
    // mask(bit12)を落とすと unmasked になり #XM で fault する。
    // destination は commit されない。
    let feats = polyisa_guest_x86::model_feats("x86_64")
        | polyisa_guest_x86::FEAT_AVX10_2
        | polyisa_guest_x86::FEAT_AVX10
        | polyisa_guest_x86::FEAT_AVX512F
        | polyisa_guest_x86::FEAT_AVX512BW
        | polyisa_guest_x86::FEAT_AVX512CD
        | polyisa_guest_x86::FEAT_AVX512DQ
        | polyisa_guest_x86::FEAT_AVX512VL;
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    env.backend.set(
        polyisa_guest_x86::sem::zreg_ref(2, 0),
        u128::from(0x3fc0_0000u32), // fp32 1.5
    );
    env.backend.set(
        polyisa_guest_x86::sem::zreg_ref(0, 0),
        u128::from(0xdead_beefu32),
    );
    // precision mask(bit12)だけ落とす。
    env.backend
        .set(polyisa_guest_x86::sem::mxcsr_ref(), 0x1f80 & !(1 << 12));
    env.backend
        .mem
        .write(
            VirtAddr(0x1000),
            &[0x62, 0xF5, 0x7D, 0x28, 0x68, 0xC2], // vcvttps2ibs xmm0,ymm2
        )
        .unwrap();
    let mut sys = ExcProbe {
        kind: None,
        addr: None,
    };
    let out = run_x86::run_mode_ex(
        &mut env,
        0x1000,
        &mut sys,
        1,
        true,
        feats,
        &polyisa_guest_x86::model_params("x86_64"),
    );
    let _ = out;
    assert_eq!(sys.kind, Some(ExceptionKind::Fp), "unmasked PE は #XM");
    // fault なので destination は書き戻されない。
    let v: u128 = env.backend.get(polyisa_guest_x86::sem::zreg_ref(0, 0));
    assert_eq!(v as u32, 0xdead_beef, "fault では非 commit");
    // MXCSR の PE flag は立つ（handler が原因を読むため）。
    let mx: u32 = env.backend.get(polyisa_guest_x86::sem::mxcsr_ref());
    assert_ne!(mx & (1 << 5), 0, "PE flag は commit される");
}

#[test]
fn run_xrstor_mxcsr_reserved_bits_gp() {
    use polyisa_sem::ExceptionKind;
    let feats = polyisa_guest_x86::model_feats("x86_64");
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    env.backend.mem.map(VirtAddr(0x2000), 1, Perms::RW).unwrap();
    // xrstor [rbx]、rbx=0x2000 は 64 バイト整列。
    env.backend
        .mem
        .write(VirtAddr(0x1000), &[0x0F, 0xAE, 0x2B])
        .unwrap();
    env.backend.set(Gpr(3).state(), 0x2000);
    env.backend.set(Gpr(0).state(), 2); // eax: RFBM bit1 (SSE)
    env.backend.set(Gpr(2).state(), 0); // edx
    env.backend.set(polyisa_guest_x86::sem::xcr0_ref(), 0x3);
    // MXCSR は領域 +24。予約 bit16 を立てる。
    env.backend
        .mem
        .write(VirtAddr(0x2000 + 24), &0x1_0000u32.to_le_bytes())
        .unwrap();
    let mut sys = ExcProbe {
        kind: None,
        addr: None,
    };
    let out = run_x86::run_mode_ex(
        &mut env,
        0x1000,
        &mut sys,
        4,
        true,
        feats,
        &polyisa_guest_x86::model_params("x86_64"),
    );
    let _ = out;
    assert_eq!(
        sys.kind,
        Some(ExceptionKind::Protection),
        "xrstor で MXCSR 予約 bit は #GP"
    );
    // 予約 bit を落とせば正常に復元される。
    env.backend
        .mem
        .write(VirtAddr(0x2000 + 24), &0x1f80u32.to_le_bytes())
        .unwrap();
    let mut sys2 = ExcProbe {
        kind: None,
        addr: None,
    };
    let out = run_x86::run_mode_ex(
        &mut env,
        0x1000,
        &mut sys2,
        1,
        true,
        feats,
        &polyisa_guest_x86::model_params("x86_64"),
    );
    assert!(matches!(out, Outcome::StepLimit { .. }));
    assert_eq!(sys2.kind, None);
    assert_eq!(env.backend.get(polyisa_guest_x86::sem::mxcsr_ref()), 0x1f80);
}

/// PKRU xstate 成分。xsave が bit9 で PKRU を 0xa80 へ書き、
/// xrstor が復元する。XSTATE_BV に bit9 がなければ初期値 0 へ戻る。
#[test]
fn run_xsave_pkru_roundtrip() {
    let feats = polyisa_guest_x86::model_feats("x86_64_v3");
    let mut env = bare_x86_env();
    let rwx = Perms(Perms::R.0 | Perms::W.0 | Perms::X.0);
    env.backend.mem.map(VirtAddr(0x1000), 1, rwx).unwrap();
    env.backend.mem.map(VirtAddr(0x2000), 1, Perms::RW).unwrap();
    // xcr0 = 0x203（x87|sse|pkru）。ユーザーモードの xsetbv は
    // 使えないので harness が直接設定する。
    env.backend.set(polyisa_guest_x86::sem::xcr0_ref(), 0x203);
    // xsave → pkru を harness 側でクリア → xrstor の往復。
    // wrpkru/rdpkru の実行配線は未整備なので、PKRU 状態の操作は
    // harness から行う（検証対象は xstate 配線）。
    let prog: &[u8] = &[
        // xsave [rbx]、mask edx:eax = 0:0x203
        0x31, 0xD2, // xor edx,edx
        0xB8, 0x03, 0x02, 0x00, 0x00, // mov eax,0x203
        0x0F, 0xAE, 0x23, // xsave [rbx]
        0x48, 0xC7, 0xC0, 0x3C, 0x00, 0x00, 0x00, // mov rax,60
        0x48, 0x31, 0xFF, // xor rdi,rdi
        0x0F, 0x05, // syscall
    ];
    env.backend.mem.write(VirtAddr(0x1000), prog).unwrap();
    env.backend.set(Gpr(3).state(), 0x2000);
    env.backend
        .set(polyisa_guest_x86::sem::pkru_ref(), 0xAABBCC00);
    let mut sys = X64Exit;
    let out = run_x86::run_mode_ex(
        &mut env,
        0x1000,
        &mut sys,
        200,
        true,
        feats,
        &polyisa_guest_x86::model_params("x86_64_v3"),
    );
    assert_eq!(out, Outcome::Exit(0));
    // xsave が 0xa80 に PKRU を書いたことを確認
    let mut buf = [0u8; 8];
    env.backend
        .mem
        .read(
            VirtAddr(0x2000 + 0xa80),
            &mut buf,
            polyisa_mem::Access::DATA_LE,
        )
        .unwrap();
    assert_eq!(
        u64::from_le_bytes(buf),
        0xAABBCC00,
        "xsave が PKRU を +0xa80 へ書く"
    );
    // XSTATE_BV（+512）に bit9 が立つことを確認
    env.backend
        .mem
        .read(
            VirtAddr(0x2000 + 512),
            &mut buf,
            polyisa_mem::Access::DATA_LE,
        )
        .unwrap();
    assert_ne!(
        u64::from_le_bytes(buf) & 0x200,
        0,
        "XSTATE_BV に bit9 が立つ"
    );
    // pkru をクリアして xrstor だけを実行する第2フェーズ
    let prog2: &[u8] = &[
        0x31, 0xD2, // xor edx,edx
        0xB8, 0x03, 0x02, 0x00, 0x00, // mov eax,0x203
        0x0F, 0xAE, 0x2B, // xrstor [rbx]
        0x48, 0xC7, 0xC0, 0x3C, 0x00, 0x00, 0x00, // mov rax,60
        0x48, 0x31, 0xFF, // xor rdi,rdi
        0x0F, 0x05, // syscall
    ];
    env.backend.mem.write(VirtAddr(0x1000), prog2).unwrap();
    env.backend.set(polyisa_guest_x86::sem::pkru_ref(), 0);
    let mut sys = X64Exit;
    let out = run_x86::run_mode_ex(
        &mut env,
        0x1000,
        &mut sys,
        200,
        true,
        feats,
        &polyisa_guest_x86::model_params("x86_64_v3"),
    );
    assert_eq!(out, Outcome::Exit(0));
    assert_eq!(
        env.backend.get(polyisa_guest_x86::sem::pkru_ref()),
        0xAABBCC00,
        "xrstor が PKRU を復元する"
    );
}
